/**
 * Integration test launcher (@vscode/test-electron). Fixture repos are
 * generated by scripts/build-fixtures.mjs (via scripts/run-integration.mjs)
 * before launch and passed as workspace folders so tests run against REAL
 * git repositories.
 *
 * Window hygiene (root-cause fix): the test electron instance gets a FRESH
 * --user-data-dir per run. Without it, @vscode/test-electron reuses a fixed
 * user-data dir whose session state accumulates cached workspaces; a dirty
 * previous run then makes VS Code restore dozens of dead "Untitled
 * (Workspace)" windows and the machine grinds to a halt. Fresh state means
 * there is never anything to restore.
 */
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { runTests } from '@vscode/test-electron';

async function main(): Promise<void> {
  const fixturesDir = process.env.JETGIT_FIXTURES_DIR;
  if (!fixturesDir) {
    throw new Error('JETGIT_FIXTURES_DIR must point at the generated fixture repos');
  }
  const extensionDevelopmentPath = path.resolve(__dirname, '..', '..');
  const repoA = path.join(fixturesDir, 'repo-a');
  const repoAWorktree = path.join(fixturesDir, 'repo-a-wt');
  const repoB = path.join(fixturesDir, 'repo-b');

  const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'jetgit-test-userdata-'));
  try {
    await runTests({
      extensionDevelopmentPath,
      extensionTestsPath: path.resolve(__dirname, './suite/index'),
      launchArgs: [
        repoA,
        repoAWorktree,
        repoB,
        '--disable-extensions',
        '--disable-gpu',
        `--user-data-dir=${userDataDir}`,
      ],
    });
  } finally {
    // Best-effort cleanup; the instance may still hold locks for a moment.
    try {
      fs.rmSync(userDataDir, { recursive: true, force: true, maxRetries: 3, retryDelay: 500 });
    } catch {
      // Leftover temp dir — harmless, the OS cleans tmp.
    }
  }
}

function fail(err: unknown): never {
  console.error('Integration tests failed', err);
  process.exit(1);
}

main().catch(fail);
